function Countdown({ compact = false }: { compact?: boolean }) {
  const [now, setNow] = useState(Date.now()); useEffect(() => { const id = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(id); }, []);
  const distance = Math.max(0, new Date('2025-10-18T20:00:00').getTime() - now);
  const values = [{ label: 'يوم', value: Math.floor(distance / 86400000) }, { label: 'ساعة', value: Math.floor(distance / 3600000) % 24 }, { label: 'دقيقة', value: Math.floor(distance / 60000) % 60 }, { label: 'ثانية', value: Math.floor(distance / 1000) % 60 }];
  return <div className="flex justify-center gap-2" dir="rtl">{values.map(item => <div key={item.label} className={`countdown-cell ${compact ? 'min-w-[48px] px-1.5 py-2' : 'min-w-[62px] p-3'}`} data-testid={`countdown-${item.label}`}><b className={compact ? 'text-lg' : 'text-2xl'}>{String(item.value).padStart(2, '0')}</b><small>{item.label}</small></div>)}</div>;
}
