  const bars = [42, 57, 49, 72, 66, 83, 61, 78]; return <div className="space-y-5"><div className="admin-summary-grid">{[['طلبات هذا الشهر', '١٢٨', 'مقابل النسخة السابقة', '+١٢٪', BarChart3], ['دعوات منشورة', '٨٤', 'دعوات في مراحل مختلفة', 'قيد المتابعة', FileText], ['إيراد تجريبي', '٢٤٬٧٨٠', 'أرقام واجهة غير متصلة بالدفع', 'EGP', Package], ['معدل تأكيد', '٦٤٪', 'من ردود العينة الحالية', 'محلي', TicketCheck]].map(([title, value, detail, note, Icon]) => <article key={title as string} className="admin-stat"><div className="flex items-center justify-between"><p className="text-sm text-muted">{title as string}</p><Icon size={18} className="text-accent" /></div><strong>{value as string}</strong><div className="mt-2 flex items-center justify-between text-xs"><span className="text-muted">{detail as string}</span><span className="text-accent">{note as string}</span></div></article>)}</div><div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><article className="admin-panel"><div className="flex items-start justify-between"><div><h2 className="font-bold text-ink">حركة الطلبات</h2><p className="mt-1 text-xs text-muted">عرض بصري لبيانات تجريبية محلية</p></div><button onClick={() => onToast('تم تحديث العرض المحلي')} className="icon-button" data-testid="button-refresh-chart"><Archive size={17} /></button></div><div className="bar-chart mt-8">{bars.map((height, i) => <div key={i} className="bar-column"><div className="bar" style={{ height: `${height}%` }} /><span>{['أحد', 'اثن', 'ثلا', 'أرب', 'خمي', 'جمع', 'سبت', 'أحد'][i]}</span></div>)}</div></article><article className="admin-panel"><div className="flex items-center justify-between"><div><h2 className="font-bold text-ink">آخر النشاطات</h2><p className="mt-1 text-xs text-muted">تحديثات محلية</p></div><Bell size={18} className="text-accent" /></div><div className="mt-6 space-y-4">{['إضافة قالب نور القمر', 'تحديث باقة فرحتنا', 'طلب جديد من مساحة تجريبية', 'تأكيد محتوى دعوة أحمد وسلمى'].map((item, i) => <div key={item} className="flex gap-3"><span className="activity-dot" /><div><p className="text-sm font-semibold text-ink">{item}</p><p className="mt-1 text-xs text-muted">منذ {i + 1} ساعات</p></div></div>)}</div></article></div></div>;
