function TemplateEditor({ templates, setTemplates, onToast }: { templates: Template[]; setTemplates: React.Dispatch<React.SetStateAction<Template[]>>; onToast: (m: string) => void }) {
  const [editing, setEditing] = useState<Template | null>(null); const [form, setForm] = useState({ name: '', category: 'Modern' as TemplateCategory, tag: '' });
  const open = (t?: Template) => { setEditing(t || null); setForm(t ? { name: t.name, category: t.category, tag: t.tag } : { name: '', category: 'Modern', tag: '' }); };
  const save = () => { if (!form.name.trim()) return; if (editing) setTemplates(prev => prev.map(t => t.id === editing.id ? { ...t, ...form } : t)); else setTemplates(prev => [...prev, { id: `custom-${Date.now()}`, ...form, className: 'template-noor', colors: ['#26364c', '#c8a77c'], active: true, featured: false, order: prev.length + 1 }]); setEditing(null); onToast('تم حفظ القالب محليًا'); };
  const remove = (id: string) => { setTemplates(prev => prev.filter(t => t.id !== id)); onToast('تم حذف القالب من العرض المحلي'); };
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="section-kicker">مكتبة التصميم</p><h2 className="mt-1 text-2xl font-bold text-ink">القوالب</h2></div><button onClick={() => open()} className="button-primary inline-flex items-center gap-2 px-4 py-2.5 text-sm" data-testid="button-admin-add-template"><Plus size={16} /> إضافة قالب</button></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{[...templates].sort((a, b) => a.order - b.order).map(t => <article key={t.id} className="admin-template-card"><TemplateCard template={t} compact onPreview={() => onToast(`معاينة ${t.name}`)} onUse={() => onToast(`تم تطبيق ${t.name} في المعاينة`)} /><div className="admin-controls"><button onClick={() => setTemplates(prev => prev.map(x => x.id === t.id ? { ...x, active: !x.active } : x))} className={t.active ? 'toggle active' : 'toggle'} data-testid={`button-toggle-template-${t.id}`}><span />{t.active ? 'نشط' : 'متوقف'}</button><button onClick={() => setTemplates(prev => prev.map(x => x.id === t.id ? { ...x, featured: !x.featured } : x))} className="admin-control-button" data-testid={`button-feature-template-${t.id}`}>{t.featured ? 'مميز' : 'تمييز'}</button><button onClick={() => open(t)} className="admin-control-button" data-testid={`button-edit-template-${t.id}`}><Edit3 size={14} /></button><button onClick={() => remove(t.id)} className="admin-control-button danger" data-testid={`button-delete-template-${t.id}`}><Trash2 size={14} /></button></div></article>)}</div>{editing !== null || form.name ? <Modal title={editing ? 'تعديل القالب' : 'إضافة قالب'} onClose={() => { setEditing(null); setForm({ name: '', category: 'Modern', tag: '' }); }}><div className="space-y-4"><label className="field-label">اسم القالب<input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} className="input mt-2" data-testid="input-template-name" /></label><label className="field-label">التصنيف<select value={form.category} onChange={e => setForm({ ...form, category: e.target.value as TemplateCategory })} className="input mt-2" data-testid="select-template-category">{['Luxury', 'Minimal', 'Floral', 'Modern', 'Classic', 'Arabic'].map(x => <option key={x}>{x}</option>)}</select></label><label className="field-label">وصف قصير<input value={form.tag} onChange={e => setForm({ ...form, tag: e.target.value })} className="input mt-2" data-testid="input-template-tag" /></label><button onClick={save} className="button-primary w-full py-3" data-testid="button-save-template">حفظ القالب</button></div></Modal> : null}</div>;
}
type PackageItem = { id: number; name: string; price: string; category: string; active: boolean; popular: boolean; order: number };
